[Authorize]
public async Task<IActionResult> SearchOwnDocuments(int limit)
{
    var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
    if (string.IsNullOrEmpty(userId))
        return Unauthorized();
    limit = Math.Clamp(limit, 1, 100);
    var results = await _db.Documents.Where(d => d.OwnerId == userId)
        .OrderBy(d => d.Id).Take(limit).ToListAsync();
    return Ok(results);
}

